import { expect, test } from "@playwright/test"
import AxeBuilder from "@axe-core/playwright"

test("send stream tool permission and refresh recovery", async ({ page }) => {
  let eventPoll = 0
  let prompted = false
  let permissionResolved = false
  await page.route("**/api/v1/**", async route => {
    const url = new URL(route.request().url())
    if (url.pathname === "/api/v1/sessions" && route.request().method() === "POST") return json(route, { sessionId: "session-1" }, 201)
    if (url.pathname.endsWith("/snapshot")) return json(route, { sessionId: "session-1", transcript: [], lastEventSeq: 0, lastStreamSeq: 0 })
    if (url.pathname.endsWith("/prompt")) { prompted = true; return json(route, { runId: "run-1" }, 202) }
    if (url.pathname.includes("/permissions/")) { permissionResolved = true; return json(route, { resolved: true }) }
    if (url.pathname.endsWith("/events")) {
      if (!prompted) return json(route, { events: [] })
      eventPoll++

after.content:
  await page.goto("/")
  await page.getByRole("button", { name: "New session" }).click()
  await expect(page).toHaveURL(/\/hosts\/local-host\/workspaces\/local\/sessions\/session-1/)
  await page.getByRole("textbox", { name: "Message" }).fill("echo hello")
  await page.getByRole("button", { name: "Send" }).click()
  await expect(page.getByText("Working")).toBeVisible()
  await expect(page.getByRole("alertdialog")).toBeVisible()
  await page.getByRole("button", { name: "Allow" }).click()
  await expect(page.getByLabel("echo tool completed")).toContainText("echoed hello")
  await expect(page.getByText("Done")).toBeVisible()
  await expect(page.getByText("Ready")).toBeVisible()

  if (test.info().project.name.includes("mobile")) {
    await page.getByRole("button", { name: "Open navigation" }).click()
    await expect(page.getByRole("dialog", { name: "Navigation" })).toBeVisible()
    await page.getByRole("button", { name: "Close" }).click()
  } else {
    await expect(page.getByRole("navigation", { name: "Primary" })).toBeVisible()
  }

  const results = await new AxeBuilder({ page }).analyze()
  expect(results.violations.filter(item => ["critical", "serious"].includes(item.impact ?? ""))).toEqual([])

  await page.reload()
  await expect(page.getByRole("heading", { name: "Quick Chat" })).toBeVisible()
  await expect(page.getByLabel("Composer configuration")).toContainText("faux/faux-1")
})

test("fixed Search Activity Resources and Settings routes", async ({ page }) => {
  await page.route("**/api/v1/**", async route => {
    const url = new URL(route.request().url())
    if (url.pathname === "/api/v1/host") return json(route, { hostId: "local-host", capabilities: [] })
    if (url.pathname === "/api/v1/search") return json(route, { hits: [{ sessionId: "session-1", entryId: "message-1", role: "user", snippet: "<mark>auth</mark> flow", rank: -1 }], nextCursor: "" })
    if (url.pathname === "/api/v1/sessions") return json(route, { sessions: [], nextCursor: "" })
    return json(route, {})
  })
  await page.goto("/hosts/local-host/search")
  await page.getByLabel("Search session titles and messages").fill("auth")
  await page.getByRole("button", { name: "Search" }).click()
  await expect(page.getByText("auth flow")).toBeVisible()
  await page.goto("/hosts/local-host/activity")
  await expect(page.getByRole("heading", { name: "Activity" })).toBeVisible()
  await page.goto("/hosts/local-host/resources/context-files")
  await expect(page.getByRole("tab", { name: "Context Files" })).toHaveAttribute("data-state", "active")
  await page.goto("/settings/hosts/local-host/general")
  await expect(page.getByRole("heading", { name: "Provider profiles" })).toBeVisible()
  await expect(page.getByText(/HTTP endpoints transmit/)).toBeVisible()
})

async function json(route: import("@playwright/test").Route, body: unknown, status = 200) {
  await route.fulfill({ status, contentType: "application/json", body: JSON.stringify(body) })
}
